usage.code:
import { CardStackSwap as CardSwap, CardStackSwap } from "solen-design/react";

const items = [
  { title: "Golden hour", icon: "🌇", image: "…" },
  { title: "Black beach", icon: "🏖️", image: "…" },
  { title: "Steel arches", icon: "🌉", image: "…" },
  { title: "Pink drift", icon: "☁️", image: "…" }
];

<div style={{ width: 560, height: 440 }}>
  <CardSwap
    items={items}
    theme="dark"
    cardDistance={60}
    verticalDistance={70}
    depth={90}
    skewAmount={6}
    visibleCards={4}
    delay={4000}
    autoplay={true}
    pauseOnHover={true}
    draggable={true}
    speed={1}
    bounce={0.35}
    parallax={0.5}
    hoverSpread={0.12}
    dim={0.5}
    cardRadius={18}
    intro={true}
    onChange={(frontIndex) => console.log(frontIndex)}
  />
</div>
